PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE `proxy_host` (`id` integer not null primary key autoincrement, `created_on` datetime not null, `modified_on` datetime not null, `owner_user_id` integer not null, `is_deleted` integer not null default '0', `domain_names` json not null, "forward_host" varchar(255) not null, `forward_port` integer not null, `access_list_id` integer not null default '0', `certificate_id` integer not null default '0', `ssl_forced` integer not null default '0', `caching_enabled` integer not null default '0', `block_exploits` integer not null default '0', `advanced_config` text not null default '', `meta` json not null, `allow_websocket_upgrade` integer not null default '0', `http2_support` integer not null default '0', `forward_scheme` varchar(255) not null default 'http', `enabled` integer not null default '1', `locations` json, `hsts_enabled` integer not null default '0', `hsts_subdomains` integer not null default '0', `trust_forwarded_proto` tinyint not null default '0');
CREATE TABLE `dead_host` (`id` integer not null primary key autoincrement, `created_on` datetime not null, `modified_on` datetime not null, `owner_user_id` integer not null, `is_deleted` integer not null default '0', `domain_names` json not null, `certificate_id` integer not null default '0', `ssl_forced` integer not null default '0', `advanced_config` text not null default '', `meta` json not null, `http2_support` integer not null default '0', `enabled` integer not null default '1', `hsts_enabled` integer not null default '0', `hsts_subdomains` integer not null default '0');
CREATE TABLE `setting` (`id` varchar(255) not null, `name` varchar(100) not null, `description` varchar(255) not null, `value` varchar(255) not null, `meta` json not null, primary key (`id`));
CREATE TABLE IF NOT EXISTS "redirection_host" (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL, `created_on` datetime NOT NULL, `modified_on` datetime NOT NULL, `owner_user_id` integer NOT NULL, `is_deleted` integer NOT NULL DEFAULT '0', `domain_names` json NOT NULL, `forward_domain_name` varchar(255) NOT NULL, `preserve_path` integer NOT NULL DEFAULT '0', `certificate_id` integer NOT NULL DEFAULT '0', `ssl_forced` integer NOT NULL DEFAULT '0', `block_exploits` integer NOT NULL DEFAULT '0', `advanced_config` text NOT NULL DEFAULT '', `meta` json NOT NULL, `http2_support` integer NOT NULL DEFAULT '0', `enabled` integer NOT NULL DEFAULT '1', `hsts_enabled` integer NOT NULL DEFAULT '0', `hsts_subdomains` integer NOT NULL DEFAULT '0', `forward_scheme` varchar(255) NOT NULL DEFAULT 'auto', `forward_http_code` integer NOT NULL DEFAULT '302');
COMMIT;
